(()=>{'use strict';const $=s=>document.querySelector(s);let state,busy=false,pilotLoading=false,pilotStarting=false;const pilotRequestId=crypto.randomUUID();if(new URLSearchParams(location.search).has('settings'))$('#aqsi-back').hidden=true;
async function api(path,body){const r=await fetch('/api/admin/aqsi/'+path,{cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});let d;try{d=await r.json();}catch{throw Error('Сервер не ответил. Обновите страницу и проверьте сохранение.');}if(!r.ok)throw Object.assign(Error(d.error||'Не удалось выполнить запрос.'),{status:r.status});return d;}
function show(d){state=d;$('#aqsi-live-mode').textContent=(d.paymentsEnabled||d.rentalPaymentsEnabled)?'Карта и QR СБП на одном экране CS50. Подключены: '+[d.paymentsEnabled?'заказы кафе из админки':'',d.rentalPaymentsEnabled?'выдача проката и доплаты за продление':''].filter(Boolean).join(', ')+'.':'Оплата заказов через кассу выключена.';$('#aqsi-device').value=d.deviceId||'';$('#aqsi-key').value='';$('#aqsi-key-note').textContent=d.configured?'Ключ сохранён. Оставьте поле пустым, чтобы сохранить прежний ключ.':'Ключ хранится только на сервере. После сохранения он не отображается.';}
async function action(fn){if(busy)return;busy=true;$('#aqsi-form').querySelectorAll('button,input').forEach(e=>e.disabled=true);$('#aqsi-message').textContent='Проверяем…';try{await fn();}catch(e){$('#aqsi-message').textContent=e.message;}finally{busy=false;$('#aqsi-form').querySelectorAll('button,input').forEach(e=>e.disabled=false);}}
$('#aqsi-form').onsubmit=e=>{e.preventDefault();action(async()=>{const body={revision:state.revision,deviceId:Number($('#aqsi-device').value),apiKey:$('#aqsi-key').value};try{show(await api('settings',body));$('#aqsi-message').textContent='Подключение сохранено. Теперь проверьте связь.';}finally{$('#aqsi-key').value='';}});};
$('#aqsi-check').onclick=()=>action(async()=>{if($('#aqsi-key').value||Number($('#aqsi-device').value)!==state.deviceId)throw Error('Сначала сохраните изменения.');const d=await api('check',{});$('#aqsi-message').textContent='Доступ к aQsi подтверждён. Касса: '+(d.device.model||d.device.id)+(d.device.serialNumber?' · '+d.device.serialNumber:'')+((d.paymentsEnabled||d.rentalPaymentsEnabled)?'. Оплата через кассу включена.':'. Оплата заказов выключена.');});
async function loadPilot(){if(pilotLoading)return;pilotLoading=true;try{const d=await api('pilot');$('#aqsi-pilot-start').disabled=Boolean(d.latest)||pilotStarting;$('#aqsi-pilot-status').textContent=d.latest?d.latest.label+(d.latest.receiptId?' · Чек подтверждён в aQsi':''):'Проверка ещё не запускалась.';}catch(e){$('#aqsi-pilot-start').disabled=true;$('#aqsi-pilot-status').textContent=e.message;}finally{pilotLoading=false;}}
$('#aqsi-pilot-start').onclick=async()=>{if(pilotStarting)return;if(!confirm('Запустить реальную оплату картой или СБП на 1 ₽ и фискальный чек «Лимонад» на CS50?'))return;pilotStarting=true;$('#aqsi-pilot-start').disabled=true;try{await api('pilot',{requestId:pilotRequestId,confirmAmountCents:100});}catch(e){$('#aqsi-pilot-status').textContent=e.message;}finally{await loadPilot();}};
setInterval(()=>{if(!document.hidden&&!$('#aqsi-pilot').hidden)loadPilot();},5000);
(async()=>{try{show(await api('settings'));$('#aqsi-form').hidden=false;$('#aqsi-pilot').hidden=false;await loadPilot();$('#aqsi-message').textContent=state.configured?'Подключение сохранено. Можно проверить доступ к кассе.':'Сохраните ключ из aQsi → Настройки → Интеграции → API и ID кассы.';}catch(e){$('#aqsi-message').textContent=e.message;$('#aqsi-login').hidden=e.status!==401;}})();})();
